// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(actor != address(c) && actor != address(this));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        uint256 before = address(c).balance;
        vm.prank(actor);
        c.withdrawAll();
        uint256 afterFirst = address(c).balance;
        assertTrue(afterFirst == before - amount, "first withdrawal paid exactly once");
        vm.prank(actor);
        c.withdrawAll();
        assertTrue(address(c).balance == afterFirst, "credit must be zeroed after withdrawal: no second payout");
    }
}
